{
  "research_problems": [
    {
      "text": "Ensuring that continuous-time Markov chain (CTMC) models accurately represent the behavior of component-based software to support valid quality property analysis and software engineering decisions.",
      "original_text": "As such, ensuring that the analysis is accurate by using CTMCs that closely model the behaviour of the analysed software has received relatively little attention."
    },
    {
      "text": "Improving the accuracy of quality property analysis of software systems modeled by CTMCs, overcoming the limitations of the exponential distribution assumption for operation execution times.",
      "original_text": "Our paper addresses this challenge for continuous-time Markov chains (CTMCs), a type of stochastic state-transition models used to analyse quality software properties both at design time and at runtime."
    }
  ],
  "research_questions": [
    {
      "text": "How effective are OMNI models at predicting quality property values for other system runs than the one used to collect the datasets used for the refinement?",
      "original_text": "We evaluated OMNI experimentally to answer the following research questions (RQs). RQ1 (Accuracy): How effective are OMNI models at predicting quality property values for other system runs than the one used to collect the datasets used for the refinement?"
    },
    {
      "text": "What is the effect of varying the refinement granularity on the model accuracy, size and verification time?",
      "original_text": "RQ2 (Refinement Granularity): What is the effect of varying the refinement granularity on the model accuracy, size and verification time?"
    },
    {
      "text": "What is the effect of the training dataset size on the refined model accuracy?",
      "original_text": "RQ3 (Training dataset size): What is the effect of the training dataset size on the refined model accuracy?"
    },
    {
      "text": "How does OMNI compare to a single-stage PHD fitting approach?",
      "original_text": "RQ4 (Comparison to PHD): How does OMNI compare to a single-stage PHD fitting approach?"
    }
  ],
  "background_concepts": [
    {
      "name": "Continuous-Time Markov Chains (CTMCs)",
      "description": "Mathematical models for stochastic processes evolving in time with the Markov property, used to analyze quality properties of software.",
      "original_text": "Markov chains are mathematical models for stochastic processes evolving in time. A continuous-time stochastic process X(t) with countable state space S is a continuous-time Markov chain (CTMC) if it has the Markov property."
    },
    {
      "name": "Continuous Stochastic Logic (CSL)",
      "description": "A logic used to specify quality properties over CTMCs, supporting probabilistic and steady-state operators for model checking.",
      "original_text": "OMNI uses continuous stochastic logic (CSL) extended with rewards to specify the quality properties analysed over CTMCs."
    },
    {
      "name": "Phase-Type Distributions (PHDs)",
      "description": "Distributions used to model variations in execution times of software components more accurately than exponential distributions in CTMCs.",
      "original_text": "OMNI comprises two stages. The first stage makes the CTMC more realistic through the addition of states and transitions that model the fact that software components have non-zero minimum execution times. We use additional states and transitions corresponding to Erlang distributions for this purpose. The CTMC is then further refined in the second OMNI stage by using phase-type distributions to model the variations in the execution time of the components."
    }
  ],
  "contributions": [
    {
      "name": "OMNI Method",
      "description": "A tool-supported observation-based Markov chain refinement method that improves the accuracy of CTMC models for software quality property analysis by refining high-level CTMCs using observed execution times of components.",
      "original_text": "We introduce an observation-based Markov chain refinement (OMNI) method that significantly improves the accuracy with which quality software properties can be analysed. OMNI starts from a high-level abstract CTMC whose states correspond to operations performed by different components of the analysed system, and uses observed execution times for the components to refine this CTMC."
    },
    {
      "name": "Two-Stage CTMC Refinement Approach",
      "description": "A two-stage refinement process where the first stage models minimum execution times using Erlang distributions and the second stage models execution time variations using phase-type distributions, resulting in more accurate CTMCs.",
      "original_text": "OMNI comprises two stages. The first stage makes the CTMC more realistic through the addition of states and transitions that model the fact that software components have non-zero minimum execution times. We use additional states and transitions corresponding to Erlang distributions for this purpose. The CTMC is then further refined in the second OMNI stage by using phase-type distributions to model the variations in the execution time of the components."
    },
    {
      "name": "Tool Implementation and Case Study",
      "description": "A tool implementing OMNI that produces refined CTMC models compatible with probabilistic model checkers like PRISM, demonstrated through a case study showing improved accuracy and avoidance of invalid design decisions.",
      "original_text": "In addition, we provide a tool that implements the OMNI method, producing refined CTMC models that can be analysed with the probabilistic model checker PRISM. Finally, we present a case study that shows how software engineers can use OMNI to avoid multiple invalid design decisions suggested by traditional CTMC analysis."
    }
  ]
}

{
  "research_problems": [
    {
      "text": "Real-life data used in software architecture for continuous experimentation and self-adaptation often contain invalid or wrong values that bias data analysis and decision-making.",
      "original_text": "One issue in data-driven decisions is that real-life data coming from running systems can contain invalid or wrong values which can bias the result of data analysis."
    },
    {
      "text": "Existing anomaly detection methods are either absent in runtime decision-making or difficult to tailor to domain-specific needs.",
      "original_text": "However, currently, anomaly detection is either absent in runtime decision-making approaches for continuous experimentation and self-adaptation or difficult to tailor to domain-specific needs."
    },
    {
      "text": "There is a need for a generic and tunable anomaly detection framework that can be adapted to different domains and incorporate expert input.",
      "original_text": "In this paper, we contribute by proposing a framework that simplifies the detection of data anomalies in timeseries-outputs of running systems. The framework is generic, since it can be employed in different domains, and tunable, since it uses expert user input in tailoring anomaly detection to the needs and assumptions of each domain."
    }
  ],
  "research_questions": [],
  "background_concepts": [
    {
      "name": "Anomaly",
      "description": "An observation that departs from the expected or usual behavior in data.",
      "original_text": "An anomaly is an observation that departs from the expected or usual behavior."
    },
    {
      "name": "Anomaly Detection",
      "description": "The task of defining a region that represents normal behavior and identifying observations outside this region.",
      "original_text": "Anomaly detection is therefore the task of defining a region that represents normal behavior and identifying the observations that lie outside of this region."
    },
    {
      "name": "Contextuality of Anomalies",
      "description": "Dimension describing whether anomalies depend on the context in which they occur (e.g., specific hour, day, or week) or are independent of context.",
      "original_text": "Contextuality, i.e. whether anomalies are independent of the context in which they occur (e.g. extremely high or low values or null values) or are deviations from the values expected to be observed in a specific context, e.g. in a specific hour, day, or week."
    },
    {
      "name": "Consecutiveness of Anomalies",
      "description": "Dimension describing whether anomalies are isolated or occur in a sequence.",
      "original_text": "Consecutiveness, i.e. whether anomalies are isolated from each other or occur in a sequence."
    },
    {
      "name": "Categories of Anomalies",
      "description": "Four categories based on contextuality and consecutiveness: Type I (isolated non-contextual), Type II (sequential non-contextual), Type III (isolated contextual), Type IV (sequential contextual).",
      "original_text": "Table I depicts the four different categories of anomalies that can be identified based on the above dimensions."
    }
  ],
  "contributions": [
    {
      "name": "A Tunable Anomaly Detection Framework",
      "description": "A generic and tunable framework for detecting anomalies in time series data that incorporates expert user input to tailor detection to domain-specific needs.",
      "original_text": "In this paper, we contribute by proposing a framework that simplifies the detection of data anomalies in timeseries-outputs of running systems. The framework is generic, since it can be employed in different domains, and tunable, since it uses expert user input in tailoring anomaly detection to the needs and assumptions of each domain."
    },
    {
      "name": "Two-Stage Anomaly Detection Method",
      "description": "A semi-automated method that identifies strong seasonal patterns and critical anomaly thresholds, allowing automated anomaly detection after an initial learning phase with expert input.",
      "original_text": "Concretely, anomaly detection should consider the running experiments and their expected effect, e.g. whether they change the model of normal behavior of a timeseries. At the same time, the experimentation engine should be aware of the expected anomalies (e.g. due to external circumstances such as holidays) in the timeseries of a system metric. In response, in this paper we provide a simple yet robust way to detect anomalies in arbitrary timeseries and connect anomaly detection to experimentation and self-adaptation. Our method works in two stages: identification of strong seasonal patterns and identification of critical anomaly thresholds. It is a semi-automated method in the sense that, although it assumes the involvement of domain experts in the learning phase, it can work in a completely automated way after that."
    },
    {
      "name": "Evaluation on Real-Life Traffic Data",
      "description": "Demonstrated the feasibility of the framework by successfully detecting different categories of anomalies in a real-life traffic domain time series dataset with minimal user input.",
      "original_text": "We have evaluated the feasibility of our method by applying it to identifying anomalies in a real-life data set from the traffic domain. Our results show that it is feasible to identify different categories of anomalies in the traffic data set with minimum input from a user."
    }
  ]
}

{
  "research_problems": [
    {
      "text": "Architecture Smells (ASs) are design decisions that negatively affect system quality attributes such as reusability and testability, but receive less attention than code smells in research and practice.",
      "original_text": "Architecture Smells (ASs) are design decisions that can have significant negative effects on a systems quality attributes such as reusability and testability. ASs are focused on higher level of software systems than code smells, which are implementation-level constructs. ASs can have much wider impact on a system than code smells. However, ASs usually receive less attention than code smells in both research and practice."
    },
    {
      "text": "There is a lack of empirical studies focusing on practitioners' perception of ASs and how they detect and refactor ASs.",
      "original_text": "There is a lack of empirical studies focusing on practitioners perception of ASs and how they detect and refactor ASs."
    },
    {
      "text": "There is a lack of empirical studies focusing on practitioners' perception of ASs and how they detect and refactor ASs.",
      "original_text": "Despite that researchers proposed a catalogue of ASs and corresponding architectural refactorings 8 , it is not clear how well their definitions of ASs are accepted and to what extent their refactoring approaches and tools are adopted by practitioners when detecting and refactoring ASs. There is a lack of empirical studies focusing on practitioners perception of ASs and how they detect and refactor ASs."
    }
  ],
  "research_questions": [
    {
      "text": "RQ1: How developers describe ASs in software development?",
      "original_text": "RQ1: How developers describe ASs in software development?"
    },
    {
      "text": "RQ1.1: What is the classification of ASs according to their descriptions?",
      "original_text": "RQ1.1: What is the classification of ASs according to their descriptions?"
    },
    {
      "text": "RQ2: What are the causes of ASs from the developers perspective?",
      "original_text": "RQ2: What are the causes of ASs from the developers perspective?"
    },
    {
      "text": "RQ3: What approaches or tools are used to detect and refactor ASs?",
      "original_text": "RQ3: What approaches or tools are used to detect and refactor ASs?"
    },
    {
      "text": "RQ4: What system quality attributes (such as testability and reusability) are affected by various ASs?",
      "original_text": "RQ4: What system quality attributes (such as testability and reusability) are affected by various ASs?"
    },
    {
      "text": "RQ5: What are the difficulties in detecting and refactoring ASs?",
      "original_text": "RQ5: What are the difficulties in detecting and refactoring ASs?"
    }
  ],
  "background_concepts": [
    {
      "name": "Architecture Smells (ASs)",
      "description": "Higher level design issues in software systems that negatively affect system-wide maintainability and quality attributes such as reusability and testability, distinct from code smells which are implementation-level issues.",
      "original_text": "Architecture Smells (ASs) are design decisions that can have significant negative effects on a systems quality attributes such as reusability and testability. ASs are focused on higher level of software systems than code smells, which are implementation-level constructs. ASs can have much wider impact on a system than code smells."
    },
    {
      "name": "Code Smells",
      "description": "Design issues at the code level that degrade understandability and changeability, resulting in poor maintainability and hindering system evolution.",
      "original_text": "Code smells are design issues that degrade understandability and changeability at the code level, which results in poor maintainability and hinders evolution of a system."
    },
    {
      "name": "Design Smells",
      "description": "Violations of design principles such as acyclic dependencies principle, impacting a set of classes in design structure.",
      "original_text": "Design smells indicate violation of design principles such as acyclic dependencies principle, and have a potential impact on a set of classes in design structure."
    },
    {
      "name": "Architectural Refactoring",
      "description": "The process of removing architecture smells to improve software quality, analogous to code refactoring which removes code smells.",
      "original_text": "Architectural refactoring, akin to code refactoring, is used to remove ASs."
    },
    {
      "name": "Grounded Theory",
      "description": "An interpretive research method used to generate concepts, categories, and theory from qualitative data through systematic bottom-up analysis.",
      "original_text": "We used Grounded Theory method for analyzing the extracted posts about developers description of ASs, causes of ASs, approaches and tools for detecting and refactoring ASs, quality attributes affected by ASs, and difficulties in detecting and refactoring ASs."
    },
    {
      "name": "Stack Overflow",
      "description": "A popular online questions and answers platform for developers to ask and answer software development questions, used as a data source for empirical studies.",
      "original_text": "Stack Overflow has been a most popular and widely used questions and answers (Q A) platform for developers to ask and answer questions since 2008."
    }
  ],
  "contributions": [
    {
      "name": "Exploratory Study on Developers' Perception of Architecture Smells",
      "description": "Conducted an exploratory study analyzing 207 Stack Overflow posts using Grounded Theory to understand how developers describe, cause, detect, refactor, and perceive the impact and challenges of Architecture Smells.",
      "original_text": "We have conducted an exploratory study of developers conception of ASs by analyzing related discussions in Stack Overflow. We used 14 ASs related terms to search the relevant posts in Stack Overflow and extracted 207 posts. We used Grounded Theory method for analyzing the extracted posts about developers description of ASs, causes of ASs, approaches and tools for detecting and refactoring ASs, quality attributes affected by ASs, and difficulties in detecting and refactoring ASs."
    },
    {
      "name": "Identification of Key Findings on Architecture Smells",
      "description": "Found that developers often use general terms to describe ASs; ASs are mainly caused by violating architecture patterns, design principles, or misusing architecture antipatterns; there is a lack of dedicated tools for detecting and refactoring ASs; maintainability and performance are main concerns; and challenges include inability to quantify cost-benefit and lack of approaches and tools.",
      "original_text": "Our findings show that: (1) developers often describe ASs with some general terms; (2) ASs are mainly caused by violating architecture patterns, design principles, or misusing architecture antipatterns; (3) there is a lack of dedicated tools for detecting and refactoring ASs; (4) developers mainly concern about the maintainability and performance of systems affected by ASs; and (5) the inability to quantify the cost and benefit as well as the lack of approaches and tools makes detecting and refactoring ASs difficult."
    }
  ]
}

{
  "research_problems": [
    {
      "text": "Cyber-physical systems are vulnerable to information leaks, and software architects need to reason about security policies to define desired and undesired information flow through a system, especially when using microservice architectures that require refinement of macro-level policies into micro-level policies for individual microservices.",
      "original_text": "Since cyber-physical systems are inherently vulnera- ble to information leaks, software architects need to reason about security policies to define desired and undesired information flow through a system. The microservice architectural style requires the architects to refine a macro-level security policy into micro-level policies for individual microservices."
    },
    {
      "text": "Ill-formed refinement of security policies in microservice compositions can lead to information leaks, and existing approaches do not adequately consider cyber-physical system characteristics like real-time behavior or asynchronous message passing communication.",
      "original_text": "However, when policies are refined in an ill-formed way, information leaks can emerge on composition of microservices. Related approaches to prevent such leaks do not take into account characteristics of cyber-physical systems like real-time behavior or message passing communication."
    },
    {
      "text": "Information flow security is not generally compositional, so even if local security policies are satisfied, their composition can introduce global information leaks, which is a challenge in microservice architectures with finer-grained policies.",
      "original_text": "Using these lo- cal policies to reason about the overall system security requires compositionality of the verification. Unfortunately, it is a well- known fact that information flow security is not generally compositional. Thus, even if all local security policies are satisfied, composing them in an ill-formed way can introduce global information leaks."
    },
    {
      "text": "Existing architectural security approaches lack formal rigor of information flow or do not consider cyber-physical system characteristics such as real-time constraints, asynchronous communication, and feedback composition.",
      "original_text": "Related work on architectural security either lacks the for- mal rigor of information flow, or does not take a num- ber of cyber-physical system characteristics into account. Namely, these systems must satisfy real-time constraints imposed by their environment. The resulting time-dependent behavior must be considered during the verification to detect implicit information leaks that are exploitable by observing the systems response times. Also, existing approaches assume a synchronous handshake communication between components. In contrast, cyber-physical systems interact asynchronously by lightweight message passing. Finally, cyber-physical systems implement complex, application-level interaction protocols that are based on a two-way communication. This so-called feedback is known as the most restrictive form of composition that often prevents a compositional verification."
    },
    {
      "text": "Evaluating the accuracy of a compositional verification approach for microservice security policies using the CoCoME case study, comparing verification results of microservices against expected security outcomes to identify secure and insecure architectures.",
      "original_text": "To analyse the outcomes of our study, we compare the results obtained from the verification against the expected security results. Thereby, we check if our predefined expectations are satisfied. If the system is expected to be secure with respect to a policy, that expectation is satisfied if all the microservices are also verified as secure. In contrast, an insecure expectation is satisfied if at least one of the microservices is insecure according to the verification."
    },
    {
      "text": "Challenges in verifying microservice security policies include memory limitations of verification tools and abstraction from explicit data handling, which may mask false positives or negatives.",
      "original_text": "In case of the Application, no results are available for two policies due to excess memory usage of UPPAAL. ... our implementations omit the explicit data handling of microservices. Thus, we abstract from the way that individual parameters are processed, stored, and propagated. Thereby, we might have masked both false positive and false negative errors."
    },
    {
      "text": "Limitations in generalizing findings from the CoCoME case study to cyber-physical systems with hard real-time constraints and physical hardware interactions.",
      "original_text": "In particular, no hard real-time constraints are imposed on the system by the physical environment. Therefore, our findings might not be generalizable to cases that actually show these characteristics."
    }
  ],
  "research_questions": [],
  "background_concepts": [
    {
      "name": "MECHATRONICUML",
      "description": "A component-based design method for cyber-physical systems, comprising a domain-specific modeling language and an underlying design process that supports asynchronous message passing communication and microservice architectural style.",
      "original_text": "MECHATRONICUML is a component-based design method for cyber-physical systems, comprising a domain- specific modeling language and an underlying design process."
    },
    {
      "name": "Information Flow Security",
      "description": "A theory that analyzes system behavior with respect to information leaks by classifying information into secret, public, and neutral levels, and ensuring that secret information does not influence public information observable by third parties.",
      "original_text": "The theory of information flow security allows to analyze the behavior of a system with respect to information leaks. Intuitively, a system is secure if secrets are never made public. Thus, secret information processed by a system must not be deducible through the public information that the system ex- changes with untrusted third parties. To that end, the approach considers information at different levels of sensitivity: secret information must not be disclosed to the public. Therefore, the behavior of a system must not allow third parties to deduce which secret information is processed. public information is exchanged with third parties. Thus, the system behavior must ensure that observing this information does not enable any deductions about secrets. neutral information is neither secret nor public. In con- trast to secret information, it may be disclosed to third parties. In contrast to public information, observing neu- tral information may enable deductions about secrets."
    },
    {
      "name": "Perturbation Correction",
      "description": "A concept in information flow security where changes in secret information (perturbations) must not influence public information, but may influence neutral information which can be used for correction to keep public information uninfluenced.",
      "original_text": "Information flow security requires the behavior of a system to prevent secret information from influencing public information. In order to define the meaning of influence more precisely, the approach relies on the notion of perturbation. A perturbation is a change in the amount of the secret information that a system processes during an execution. Perturbing secret information must have no influence on the public information processed during that execution, otherwise an information flow from secret to public would be possible. Perturbations of secret information may, however, influence neutral information. This is an important factor as it allows for a correction in response to a pertur- bation. By means of a correction, a system adjusts the amount of neutral information processed during an execution, thereby allowing the public information to remain uninfluenced."
    },
    {
      "name": "Generalized Noninterference",
      "description": "An information flow security property that restricts perturbations to inputs and allows corrections via neutral inputs or outputs, preserved under asynchronous feedback composition.",
      "original_text": "Our approach is based on generalized noninterference, a traditional information flow property that restricts perturbations to inputs. Hence, to perturb a system, secret inputs are both added to or deleted from the execution. In response to the perturbation, the system may add or delete neutral inputs or outputs to produce a corrected execution without influencing any public information. Generalized noninterference is known to be preserved on feedback composition, provided that the underlying communication between the composed subsystems is asynchronous."
    },
    {
      "name": "Simulation Preorder",
      "description": "A behavioral relation used as a verification technique where the original system must simulate all public observations allowed by a perturbed variant to ensure public information is uninfluenced by secrets.",
      "original_text": "Since public information needs to be uninfluenced by secrets, the public observations allowed by a system must subsume all the public observations allowed by a perturbed variant of the same system. In the scope of state transition systems, such a behavioral relation is expressible in terms of a simulation preorder. Thus, the original system must be able to simulate all the public observations allowed by the perturbed variant. In this paper, we use simulations as our underlying verification technique."
    }
  ],
  "contributions": [
    {
      "name": "Well-formedness Rules for Security Policy Refinement",
      "description": "A set of well-formedness rules to refine an information flow security policy during the decomposition of an architecture into microservices, ensuring that the global security restrictions are enforced by the refined micro-level policies.",
      "original_text": "We provide a set of well-formedness rules to refine an in- formation flow security policy during the decomposition of an architecture into microservices."
    },
    {
      "name": "Compositional Verification Approach",
      "description": "A compositional verification technique to check microservices against their micro-level security policies, preserving security on composition even with feedback and asynchronous communication.",
      "original_text": "We present a compositional verification approach to check microservices against their security policies, and preserve security on composition."
    },
    {
      "name": "Evaluation Using CoCoME Case Study",
      "description": "An evaluation of the approach using a security-oriented extension of the CoCoME case study, demonstrating the accuracy of the approach in detecting insecure architectures.",
      "original_text": "We evaluate our approach using a security-oriented ex- tension of the CoCoME case study."
    }
  ]
}

{
  "research_problems": [
    {
      "text": "Engineering IoT systems is challenging due to dynamicity and uncertainty of the environment, including human involvement, and the need for systems to cope with dynamic changes and deployment issues.",
      "original_text": "Engineering Internet of Things (IoT) systems is a challenging task partly due to the dynamicity and uncertainty of the environment including the involvement of the human in the loop. Users should be able to achieve their goals seamlessly in different environments, and IoT systems should be able to cope with dynamic changes. Several approaches have been proposed to enable the automated formation, enactment, and self-adaptation of goal-driven IoT systems. However, they do not address deployment issues."
    },
    {
      "text": "Existing approaches for dynamic formation and adaptation of goal-driven IoT systems do not address deployment issues such as automated placement of functionalities within hardware infrastructure and self-adaptation to changes in deployment topologies.",
      "original_text": "Several approaches have been proposed to enable the dynamic formation, enactment, and self-adaptation of GDS. However, they do not address deployment issues, such as the automated placement of the GDS functionalities within a hardware infrastructure. Additionally, among the works that focus on the deployment of IoT systems, very few aim at enabling the systems to self-adapt to dynamic changes in their deployment topologies, such as, the sudden unavailability of the deployment nodes and the degradation of the quality of their services or interconnections."
    },
    {
      "text": "Deployment of goal-driven IoT systems is complex due to variability in the number and types of devices, heterogeneous hardware infrastructures, different performance requirements, and sudden changes in system constituents or deployment topologies.",
      "original_text": "The deployment of GDS is a complex process partly due to the following reasons. The number and types of the things that constitute a GDS formed to achieve a goal can be different from an environment to another based on the available devices. Moreover, the dynamically formed GDS may have different performance requirements based on the requested goals. Additionally, the hardware infrastructures in different environments are heterogeneous with respect to their processing and storage capabilities and interconnections. Furthermore, changes in the status of the systems constituents and or the deployment topologies can happen suddenly."
    }
  ],
  "research_questions": [],
  "background_concepts": [
    {
      "name": "Goal-Driven IoT System (GDS)",
      "description": "A system composed of devices with individual functionalities that connect and cooperate temporarily to achieve user goals, dynamically formed based on available devices and goals.",
      "original_text": "A Goal-Driven IoT System (GDS) is composed of a set of devices with individual functionalities that connect and cooperate temporally to achieve the user goal. In previous studies, we referred to GDS as Emergent Configurations. For instance, a GDS could be dynamically formed by connecting a light sensor and two connected lamps to achieve the goal adjust the light level in a smart meeting room."
    },
    {
      "name": "Deployment Models for IoT Systems",
      "description": "Models include Everything in the Cloud, Everything in the Edge, and Hybrid Edge-Cloud, each with different properties in terms of response time, availability, privacy, and quality characteristics.",
      "original_text": "In general, IoT systems can be deployed according to the following models: 1) Everything in the Cloud model: In this model, the software components of IoT systems are placed in the Cloud. It is suitable when the systems require significant elastic processing and storage capabilities or when their constituents are scattered in various areas. 2) Everything in the Edge model: The software components of IoT systems are placed in networks of more constrained devices with respect to the Cloud (e.g., local servers and gateways) that are at the Edge of the network. In this model, the computational capabilities are lower than those within the Cloud-based model. 3) Hybrid Edge-Cloud model: The software components of IoT systems are distributed across the Cloud and the Edge of the network. Thus, it enables exploiting the advantages of the other two models. For instance, it supports deploying the components that should perform processes with low latency in the Edge of the network, and deploying those that perform resource-demanding processes in the Cloud. These deployment models have different properties in terms of response time, availability, privacy, and other quality characteristics."
    },
    {
      "name": "MAPE-K Loop",
      "description": "A control loop model from Self-adaptive Systems consisting of Monitor, Analyze, Plan, Execute plus Knowledge components used to enable self-adaptation.",
      "original_text": "The approach exploits the notion of Monitor-Analyze-Plan- Execute plus Knowledge (MAPE-K) loop adopted from the field of Self-adaptive Systems."
    }
  ],
  "contributions": [
    {
      "name": "Goal-driven approach for deploying self-adaptive IoT systems in the Edge-Cloud continuum",
      "description": "An approach that supports dynamic deployment and self-adaptation of goal-driven IoT systems considering goal complexity, performance requirements, and dynamic changes in deployment topologies and constituent status.",
      "original_text": "In this paper, we propose a goal-driven approach for deploying self-adaptive IoT systems in the Edge- Cloud continuum. Our approach supports the systems to cope with the dynamicity and uncertainty of the environment including changes in their deployment topologies, i.e., the deployment nodes and their interconnections."
    },
    {
      "name": "Architecture and processes for deployment and self-adaptation of goal-driven IoT systems",
      "description": "An architecture comprising components such as User Agent, Goal Manager, Deployment Planner, Context Manager, Enactment Engine, Adaptation Manager, and Knowledge Base to enable deployment and self-adaptation.",
      "original_text": "Figure 1 illustrates the architecture of the approach. It comprises seven main components as described in the following. User Agent... Goal Manager... Deployment Planner... Context Manager... Enactment Engine... Adaptation Manager... Knowledge Base."
    },
    {
      "name": "Prototype implementation and simulation validation",
      "description": "A prototype implementation and simulations in smart home and smart building environments demonstrating scalability and feasibility of the approach.",
      "original_text": "To validate the feasibility of the approach, we implemented a prototype and simulated the deployment of GDS in a smart home and a smart building environments. The results of the simulations show that the approach scales well when generating and adapting the deployment topologies of goal-driven IoT systems in smart homes and smart buildings."
    }
  ]
}

{
  "research_problems": [
    {
      "text": "The paper addresses the limitation of existing probabilistic model synthesis methods that assume system parameters match exactly those of the model, which is unrealistic and limits robustness.",
