{
  "research_problems": [
    {
      "text": "It is difficult for software architects to focus their attention effectively given their broad responsibilities across technical aspects of projects.",
      "original_text": "In our research and practice in the field of software architecture, we have noticed and experienced that it is difficult for software architects to focus their attention. The software architect’s responsibilities are broad and in principle they can be involved in almost any technical aspect of a project from requirements to operational concerns."
    },
    {
      "text": "Understanding how successful software architects focus their attention and whether common role-specific heuristics exist that can be taught to new architects.",
      "original_text": "However, we also observe that successful software architects appear to be very good at focusing their attention effectively, which led us to wonder how they achieve this. They may use time management techniques (like [2]) but we wondered whether there are common role-specific heuristics which could be taught to new architects."
    }
  ],
  "research_questions": [
    {
      "text": "Are there common heuristics which experienced architects use to focus their attention?",
      "original_text": "In a previous study [15], we decided to investigate this via a questionnaire-based study of a group of experienced architects. We discovered that there are common heuristics which experienced architects use to focus their attention and we created a model to capture and relate them."
    },
    {
      "text": "How can the model of heuristics for focusing architectural attention be validated and refined with a wider group of software and enterprise architects?",
      "original_text": "In this paper we explain how, in a second study, we then validated the model with a much wider group of software and enterprise architects, via an online questionnaire, and refined the model based on their input."
    }
  ],
  "background_concepts": [
    {
      "name": "Software Architecture",
      "description": "The discipline involving the design and organization of software systems, encompassing technical aspects from requirements to operational concerns.",
      "original_text": "The software architect’s responsibilities are broad and in principle they can be involved in almost any technical aspect of a project from requirements to operational concerns."
    },
    {
      "name": "Heuristics in Software Architecture",
      "description": "Role-specific heuristics used by experienced software architects to focus their attention effectively during projects.",
      "original_text": "We discovered that there are common heuristics which experienced architects use to focus their attention and we created a model to capture and relate them."
    },
    {
      "name": "Risk-Driven Architecture",
      "description": "An architectural method that prioritizes architectural decisions based on risk and cost to guide architects on where to focus their attention.",
      "original_text": "When we started investigating this topic, we were primarily interested in how practitioners really worked. However, we also performed a literature search to find related work from the research community. We did not find any studies investigating the specific topic we are interested in, but an architectural method which helps architects to focus their attention is Risk and Cost Driven Architecture (RCDA) [11]. This method transforms the architect’s approach from defining architectural structures early in a project, to providing a stream of decisions throughout it, prioritising their work using the risk and cost of open decisions."
    }
  ],
  "contributions": [
    {
      "name": "Validated Model of Heuristics for Focusing Architectural Attention",
      "description": "A simple, coherent model capturing common heuristics used by experienced software architects to focus their attention effectively, validated with a broad group of practitioners.",
      "original_text": "The contribution of our work is not the heuristics in our model, as most of them are quite familiar to experienced practitioners. Our contribution is to capture them clearly in a simple, coherent model, and to validate their value to experienced practitioners. Our work makes the implicit knowledge held in the heads of experienced architects explicit and accessible."
    }
  ]
}

{
  "research_problems": [
    {
      "text": "Updating air-gapped service-based software systems in mission-critical settings poses challenges including ensuring verifiably correct update configurations, managing containerized services with different runtime environments, and recording update actions for auditability and regulatory compliance.",
      "original_text": "However, updating air-gapped systems raises several issues from a software architecture perspective, especially given the overall mission-critical setting; those include: (i) the configuration of components produced to update the system should be verifiably correct, since there is significant cost-to-repair for incorrect updates, (ii) service-based architectures entail containerized services, with support of different runtime environments, and (iii) update actions should be recorded in a traceable manner, in order to support auditability and regulatory compliance."
    }
  ],
  "research_questions": [],
