{
  "research_problems": [
    {
      "text": "Updating PLC/DCS programs without production stop is challenging due to the need for fast state transfer to maintain continuous control signal output.",
      "original_text": "Updating PLC/DCS programs shall ideally not require a production stop, which can incur high costs for the associated machinery and processes. Patching PLC runtimes or applications is therefore undesired and only rarely done. Container orchestration (e.g., Kubernetes) allows switching to an updated virtual runtime or application in another container “on-the-fly”, by transferring the signal input subscriptions and output publications. However, the newly started runtime or program need to work with the same internal state (i.e. a set of variables storing intermediate calculations) as the former runtime. Due to the short execution cycles (e.g., every 100 ms), the required state transfer from container to container needs to be fast, so that the control actuators continuously receive their control signals without interruption."
    }
  ],
  "research_questions": [],
  "background_concepts": [
    {
      "name": "PLCs and DCSs",
      "description": "Programmable Logic Controllers and Distributed Control Systems used in industrial production processes for automation, typically running control algorithms cyclically with real-time constraints.",
      "original_text": "PLCs and DCSs are at the heart of many industrial production processes, such as power generation, mining, chemical production, or paper production [6]. The DCS is market size is at 13.4 BUSD in 2020 and expected to grow significantly in the next few years [3]. PLCs and DCSs receive telemetry data from sensors and cyclically run control algorithms that produce output signals for various actuators, such as motors, pumps, mixers, reactors, heat exchangers, etc. This typically relies on embedded controllers running on purpose-built hardware for high reliability."
    },
    {
      "name": "Container Orchestration (Kubernetes)",
      "description": "A system to manage containerized applications, allowing deployment, scaling, and management of containers, including features for updating applications on-the-fly.",
      "original_text": "Container orchestration (e.g., Kubernetes) allows switching to an updated virtual runtime or application in another container “on-the-fly”, by transferring the signal input subscriptions and output publications."
    },
    {
      "name": "IEC 61131-3",
      "description": "A standard defining five programming languages for industrial controllers, including function block diagrams, structured text, and ladder logic, used for programming PLCs.",
      "original_text": "A set of five different programming languages for these controllers was standardized as IEC 61131-3 in the early 1990th, including function block diagrams, structured text, and ladder logic [6]. IEC 61131-3 control runtimes execute algorithms such as ‘PID controllers’, cyclically, usually with cycle times between 10 and 1000 ms."
    },
    {
      "name": "OPC UA",
      "description": "An industrial communication protocol providing middleware and information modeling for industrial applications, supporting client/server and publish/subscribe communication for monitoring and control.",
      "original_text": "OPC UA provides a middleware and information modeling for industrial applications [10]. It is designed for monitoring industrial devices from workstations, but was lately extended to also support fast, deterministic controller-to-field device communication [2]. OPC UA includes a client/server protocol on top of TCP/IP, as well as a publish/subscribe mechanism on top of UDP."
    }
  ],
  "contributions": [
    {
      "name": "State-transfer approach for dynamic updates of Virtual PLCs",
      "description": "A novel architecture and procedure for transferring internal state between Virtual PLC runtimes deployed as Kubernetes microservices, enabling updates without interrupting control processes.",
      "original_text": "We propose a novel state-transfer approach for dynamic updates of Virtual PLCs deployed as K8s microservices. The contributions of this paper are 1) a conceptual architecture for a state transfer method that utilizes the capabilities of a container orchestration framework, 2) a procedure for state transfer across network nodes while adhering to industry standards, and 3) a rationalization of the design decisions for the entire architecture."
    },
    {
      "name": "Implementation and validation of the approach",
      "description": "An implementation based on open-source components and experiments simulating updates of large control applications with up to 500K internal state variables, demonstrating fast state transfer within cycle times.",
      "original_text": "To validate the approach, we have implemented the conceptual architecture exemplary based on open-source components (i.e., OpenPLC, Open62541, Cereal, Kubernetes, Docker). In a series of experiments, we simulated updating large control applications derived from existing power production and mining plants with up to 500K internal state variables. For an application with 100K state variables the approach was able to transfer the internal state in less than 15 ms, which is significantly lower than the required cycle time."
    }
  ]
}

